import axios from "axios";

const gold = axios.create({
  baseURL: "https://api.gold-api.com/price/",
  timeout: 10000,
  headers: {
    "Content-Type": "application/json"
  },
});

const rate = axios.create({
  baseURL: "https://api.currencyapi.com/",
  timeout: 10000,
  headers: {
    "Content-Type": "application/json"
  },
});

export { gold, rate };
