import { rate } from "../api/axios.config";

export const rateService = {
  getUSDToTHB: async () => {
    try {
      const response = await rate.get(`v3/latest?apikey=cur_live_UqwP9AUGJhZK1Njww3nfK5qcA3FUi6iczYRubbAv&currencies=THB`);
      return response.data;
    } catch (error) {
      console.error("Error fetching gold price:", error);
      throw error;
    }
  }
};
